def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append({"color": color, "cells": cells})

    def shape_key(cells):
        variants = []
        for reflect in (1, -1):
            for rot in range(4):
                pts = []
                for r, c in cells:
                    x, y = r, c * reflect
                    for _ in range(rot):
                        x, y = y, -x
                    pts.append((x, y))
                mr = min(x for x, y in pts)
                mc = min(y for x, y in pts)
                variants.append(tuple(sorted((x-mr, y-mc) for x, y in pts)))
        return min(variants)

    candidates = []
    for ki, key in enumerate(comps):
        cells = key["cells"]
        if len(cells) < 5:
            continue

        # Find an L corner with two substantial perpendicular arms.
        for cr, cc in cells:
            for hd in (-1, 1):
                for vd in (-1, 1):
                    horizontal = [(cr, cc)]
                    x = cc + hd
                    while (cr, x) in cells:
                        horizontal.append((cr, x))
                        x += hd
                    vertical = [(cr, cc)]
                    x = cr + vd
                    while (x, cc) in cells:
                        vertical.append((x, cc))
                        x += vd

                    if len(horizontal) < 2 or len(vertical) < 2:
                        continue
                    arm_cells = set(horizontal) | set(vertical)
                    # Permit a single extra cell attached to an otherwise
                    # clean L (some examples have a small protrusion).
                    if len(cells - arm_cells) > 1:
                        continue

                    rend = horizontal[0][0]
                    cend = horizontal[-1][1]
                    vend = vertical[-1][0]
                    rlo, rhi = sorted((cr, vend))
                    clo, chi = sorted((cc, cend))

                    templates = []
                    for ti, obj in enumerate(comps):
                        if ti == ki:
                            continue
                        other = obj["cells"]
                        if all(rlo <= r <= rhi and clo <= c <= chi and
                               (r-cr)*vd > 0 and (c-cc)*hd > 0
                               for r, c in other):
                            templates.append(ti)

                    for ti in templates:
                        wanted = shape_key(comps[ti]["cells"])
                        for oi, obj in enumerate(comps):
                            if oi == ki or oi == ti:
                                continue
                            if shape_key(obj["cells"]) != wanted:
                                continue
                            # The matching copy must be outside this L's cavity.
                            if all(rlo <= r <= rhi and clo <= c <= chi and
                                   (r-cr)*vd > 0 and (c-cc)*hd > 0
                                   for r, c in obj["cells"]):
                                continue
                            coverage = len(arm_cells & cells) / len(cells)
                            score = (len(cells), coverage,
                                     len(horizontal) + len(vertical))
                            candidates.append((score, ki, oi))

    if not candidates:
        return [row[:] for row in grid]

    _, key_i, target_i = max(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    color = comps[key_i]["color"]
    for r, c in comps[target_i]["cells"]:
        out[r][c] = color
    return out
